from typing import List

def sort_numbers(numbers: str) -> str:
    numerals = numbers.split()

    numeral_to_number = {
        'zero': 0,
        'one': 1,
        'two': 2,
        'three': 3,
        'four': 4,
        'five': 5,
        'six': 6,
        'seven': 7,
        'eight': 8,
        'nine': 9
    }

    numbers_list = [numeral_to_number[numeral] for numeral in numerals]
    sorted_numbers = sorted(numbers_list)

    sorted_numerals = [key for key, value in numeral_to_number.items() if value in sorted_numbers]

    return ' '.join(sorted_numerals)
